from fractions import Fraction
from math import cos, sin, sqrt, radians
from pathlib import Path
from typing import Any
import re

import numpy as np
import spglib


def _strip_quotes(token: str) -> str:
    if len(token) >= 2 and ((token[0] == token[-1] == "'") or (token[0] == token[-1] == '"')):
        return token[1:-1]
    return token


def _parse_cif_cell(text: str) -> np.ndarray:
    def get_value(tag: str) -> float:
        m = re.search(rf"^{re.escape(tag)}\s+(.+?)\s*$", text, re.MULTILINE)
        if not m:
            raise ValueError(f"Missing CIF tag: {tag}")
        return float(_strip_quotes(m.group(1).split()[0]))

    a = get_value("_cell_length_a")
    b = get_value("_cell_length_b")
    c = get_value("_cell_length_c")
    alpha = get_value("_cell_angle_alpha")
    beta = get_value("_cell_angle_beta")
    gamma = get_value("_cell_angle_gamma")

    ar, br, gr = map(radians, (alpha, beta, gamma))
    va = np.array([a, 0.0, 0.0])
    vb = np.array([b * cos(gr), b * sin(gr), 0.0])
    cx = c * cos(br)
    cy = c * (cos(ar) - cos(br) * cos(gr)) / sin(gr)
    cz = sqrt(max(c * c - cx * cx - cy * cy, 0.0))
    vc = np.array([cx, cy, cz])
    return np.array([va, vb, vc], dtype=float)


def _parse_atom_sites(text: str):
    lines = text.splitlines()
    i = 0
    atoms = []
    while i < len(lines):
        line = lines[i].strip()
        if line.lower() == "loop_":
            i += 1
            headers = []
            while i < len(lines) and lines[i].strip().startswith("_"):
                headers.append(lines[i].strip())
                i += 1
            if {
                "_atom_site_fract_x",
                "_atom_site_fract_y",
                "_atom_site_fract_z",
            }.issubset(headers):
                idx = {h: j for j, h in enumerate(headers)}
                while i < len(lines):
                    row = lines[i].strip()
                    if not row or row.startswith("_") or row.lower() == "loop_":
                        break
                    toks = [_strip_quotes(t) for t in row.split()]
                    if len(toks) >= len(headers):
                        atoms.append(
                            (
                                float(toks[idx["_atom_site_fract_x"]]),
                                float(toks[idx["_atom_site_fract_y"]]),
                                float(toks[idx["_atom_site_fract_z"]]),
                            )
                        )
                    i += 1
                continue
        i += 1
    return atoms


def _rationalize(value: float, max_denominator: int = 12) -> str:
    frac = Fraction(value).limit_denominator(max_denominator)
    if frac.denominator == 1:
        return str(frac.numerator)
    return f"{frac.numerator}/{frac.denominator}"


def analyze_wyckoff_position_multiplicities_and_coordinates(filepath: str) -> dict[str, dict] | dict[str, Any]:
    text = Path(filepath).read_text()
    lattice = _parse_cif_cell(text)
    frac_coords = np.array(_parse_atom_sites(text), dtype=float)
    if frac_coords.size == 0:
        return {"wyckoff_multiplicity_dict": {}, "wyckoff_coordinates_dict": {}}

    numbers = [1] * len(frac_coords)
    dataset = spglib.get_symmetry_dataset((lattice, frac_coords, numbers), symprec=1e-5)
    wyckoffs = list(dataset["wyckoffs"])

    multiplicity_dict: dict[str, int] = {}
    coordinate_dict: dict[str, list[str]] = {}

    for idx, letter in enumerate(wyckoffs):
        multiplicity_dict[letter] = multiplicity_dict.get(letter, 0) + 1
        if letter not in coordinate_dict:
            coord = frac_coords[idx] % 1.0
            coordinate_dict[letter] = [_rationalize(float(x)) for x in coord]

    return {
        "wyckoff_multiplicity_dict": multiplicity_dict,
        "wyckoff_coordinates_dict": coordinate_dict,
    }


if __name__ == "__main__":
    import json
    import sys

    result = analyze_wyckoff_position_multiplicities_and_coordinates(sys.argv[1])
    print(json.dumps(result, indent=2))
"}

